def seed_products(apps, schema_editor):
    Product = apps.get_model('myapp', 'Product')

    media_products_dir = os.path.join(settings.MEDIA_ROOT, 'products')
    os.makedirs(media_products_dir, exist_ok=True)

    for p in PRODUCTS:
        image_value = ''
        static_rel_path = p.get('static_image', '')
        if static_rel_path:
            filename = os.path.basename(static_rel_path)
            src_path = os.path.join(settings.BASE_DIR, 'myapp', 'static', static_rel_path)
            dst_path = os.path.join(media_products_dir, filename)
            if os.path.exists(src_path) and not os.path.exists(dst_path):
                try:
                    shutil.copyfile(src_path, dst_path)
                except OSError:
                    pass
            if os.path.exists(dst_path):
                image_value = f'products/{filename}'

        Product.objects.get_or_create(
            name=p['name'],
            category=p['category'],
            defaults={
                'label': p['label'],
                'description': p['description'],
                'price': p['price'],
                'old_price': p['old_price'],
                'tag': p['tag'],
                'image': image_value,
            }
        )


def remove_seeded_products(apps, schema_editor):
    Product = apps.get_model('myapp', 'Product')
    names = [p['name'] for p in PRODUCTS]
    Product.objects.filter(name__in=names).delete()


class Migration(migrations.Migration):

    dependencies = [
        ('myapp', '0003_product_wishlist_cartitem'),
    ]

    operations = [
        migrations.RunPython(seed_products, remove_seeded_products),
    ]
